const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // 1. Geometry & Time Definitions
  const nyPoint = ee.Geometry.Point([-74.0060, 40.7128]); // New York City
  const date1 = '2019-01-29';
  const date2 = '2019-02-05';

  // 2. Data Acquisition - ERA5 for air temperature
  const era5 = ee.ImageCollection('ECMWF/ERA5/DAILY');

  const temp1 = era5.filterDate(date1, '2019-01-30')
                    .filterBounds(nyPoint)
                    .select('mean_2m_air_temperature');

  const temp2 = era5.filterDate(date2, '2019-02-06')
                    .filterBounds(nyPoint)
                    .select('mean_2m_air_temperature');

  // Check collection sizes
  const count1 = temp1.size().getInfo();
  const count2 = temp2.size().getInfo();

  console.log(`Jan 29 Images: ${count1}, Feb 5 Images: ${count2}`);

  if (count1 === 0 || count2 === 0) {
    console.log("<answer>C1</answer>");
    return;
  }

  // Get mean temperature images
  const img1 = temp1.first();
  const img2 = temp2.first();

  // 3. Processing - Check valid pixels
  const count1_pixels = img1.reduceRegion({
    reducer: ee.Reducer.count(),
    geometry: nyPoint,
    scale: 1000,
    maxPixels: 1e9
  }).get('mean_2m_air_temperature').getInfo();

  const count2_pixels = img2.reduceRegion({
    reducer: ee.Reducer.count(),
    geometry: nyPoint,
    scale: 1000,
    maxPixels: 1e9
  }).get('mean_2m_air_temperature').getInfo();

  console.log(`Jan 29 Valid Pixels: ${count1_pixels}, Feb 5 Valid Pixels: ${count2_pixels}`);

  if (count1_pixels === 0 || count2_pixels === 0) {
    console.log("<answer>C2</answer>");
    return;
  }

  // 4. Calculation - Get temperatures (convert from Kelvin to Celsius)
  const temp1_val = img1.reduceRegion({
    reducer: ee.Reducer.mean(),
    geometry: nyPoint,
    scale: 1000,
    maxPixels: 1e9
  }).get('mean_2m_air_temperature').getInfo() - 273.15; // K to C

  const temp2_val = img2.reduceRegion({
    reducer: ee.Reducer.mean(),
    geometry: nyPoint,
    scale: 1000,
    maxPixels: 1e9
  }).get('mean_2m_air_temperature').getInfo() - 273.15; // K to C

  const diff = Math.abs(temp2_val - temp1_val);

  console.log(`Jan 29 Temp: ${temp1_val.toFixed(2)}°C`);
  console.log(`Feb 5 Temp: ${temp2_val.toFixed(2)}°C`);
  console.log(`Difference: ${diff.toFixed(2)}°C`);

  // 5. Validation & Final Answer
  if (temp1_val === null || temp2_val === null || isNaN(temp1_val) || isNaN(temp2_val)) {
    console.log("<answer>C3</answer>");
  } else if (diff >= 24) {
    console.log("<answer>A</answer>");
  } else {
    console.log("<answer>B</answer>");
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
